rr<-rd('scenic_corrected_regulon_edges.tsv');if(!'SREBF2'%in%rr$TF){writeLines('SREBF2 not recovered; conditional AUCell NE',file.path(B,'logs/09_aucell_NE.txt'));quit(save='no')}
a<-old('scenic_membership_Epi.tsv.gz');genes<-old('scenic_genes_Epi.tsv')$gene;stopifnot(!anyDuplicated(a$barcode),!anyDuplicated(genes));dir.create(file.path(B,'objects/aucell_parts'),showWarnings=FALSE);regkey<-digest(file.path(B,'objects/SREBF_corrected_regulons.pkl'),file=TRUE,algo='sha256');man<-fread(file.path(V1,'tables/original_source_input_manifest.tsv'));sourcehash<-man[path==objpath,sha256];stopifnot(digest(objpath,file=TRUE,algo='sha256')==sourcehash)
parts<-split(seq_len(nrow(a)),ceiling(seq_len(nrow(a))/2000));outfile<-function(i)file.path(B,'objects/aucell_parts',sprintf('SREBF_%03d.tsv.gz',i));key<-function(i)digest(list(sourcehash,a$barcode[parts[[i]]],genes,regkey,123,.05,'pyscenic0.12.1_original_training_gene_order'),algo='sha256');valid<-function(i){p<-outfile(i);file.exists(paste0(p,'.sha256'))&&identical(readLines(paste0(p,'.sha256')),key(i))&&all(file.exists(sub('.tsv.gz$',paste0('_',c('Full','M20'),'.tsv.gz'),p)))}
