if(length(need)){
 cat('Reading original RNA only for recovered SREBF AUCell\n');o<-qread(objpath,nthreads=1);x<-LayerData(o,assay='RNA',layer='data');x<-x[genes,a$barcode,drop=FALSE];rm(o);gc();tmp<-file.path(B,'objects/aucell_chunk.bin');idsfile<-file.path(B,'objects/aucell_chunk_ids.tsv')
 for(i in need){ids<-a$barcode[parts[[i]]];writeBin(as.numeric(as.matrix(x[,ids,drop=FALSE])),tmp,size=8,endian='little');fwrite(data.table(barcode=ids),idsfile,sep='\t');cmd<-paste(shQuote(file.path(P,'mp10_immune_endothelial_mechanisms_v1/venv/bin/python')),shQuote(file.path(S,'09_aucell_chunk.py')),shQuote(tmp),shQuote(idsfile),shQuote(outfile(i)));ret<-system(cmd);if(ret!=0)stop('Recovered AUCell failed chunk ',i);writeLines(key(i),paste0(outfile(i),'.sha256'));unlink(c(tmp,idsfile));cat('CHUNK',i,'/',length(parts),'\n');flush.console()}
}
